  validateOrder(order);
  const pricing = calculatePricing(order);
  const savedOrder = saveOrder(order, pricing);
  await notifyCustomer(order.customer, pricing.finalTotal);
  return { orderId: savedOrder.id, total: pricing.finalTotal };
}

function validateOrder(order: Order): void {
  if (!order.items?.length) throw new Error('No items');
  if (!order.customer) throw new Error('No customer');
  if (!order.shippingAddress) throw new Error('No shipping address');
}

function calculatePricing(order: Order): OrderPricing {
  const subtotal = order.items.reduce((sum, item) => sum + item.price * item.quantity, 0);
  const tax = subtotal * 0.08;
  const shipping = subtotal > 100 ? 0 : 9.99;
  const discount = calculateDiscount(order, subtotal + tax + shipping);
  return { subtotal, tax, shipping, discount, finalTotal: subtotal + tax + shipping - discount };
}

function calculateDiscount(order: Order, total: number): number {
  if (order.customer.isPremium) return total * 0.1;
  if (order.promoCode === 'SAVE20') return total * 0.2;
  if (order.items.length > 5) return total * 0.05;
  return 0;
}
