class BaseService<T, TInput> {
  constructor(
    private collection: Collection<T>,
    private entityName: string
  ) {}

  create(data: TInput): T {
    const entity = { ...data, createdAt: new Date() } as T;
    const result = this.collection.insert(entity);
    logger.info(`${this.entityName} created: ${result.id}`);
