interface ShippingStrategy {
  calculateCost(weight: number): number;
}

class StandardShipping implements ShippingStrategy {
  private rates = [
    { maxWeight: 1, cost: 5.99 },
    { maxWeight: 5, cost: 9.99 },
    { maxWeight: 20, cost: 14.99 },
    { maxWeight: Infinity, cost: 24.99 },
  ];

  calculateCost(weight: number): number {
    return this.rates.find(r => weight < r.maxWeight)?.cost ?? 24.99;
  }
}

class ExpressShipping implements ShippingStrategy {
  private rates = [
    { maxWeight: 1, cost: 12.99 },
    { maxWeight: 5, cost: 19.99 },
    { maxWeight: 20, cost: 29.99 },
    { maxWeight: Infinity, cost: 49.99 },
  ];

  calculateCost(weight: number): number {
    return this.rates.find(r => weight < r.maxWeight)?.cost ?? 49.99;
  }
}

const shippingStrategies: Record<string, ShippingStrategy> = {
  standard: new StandardShipping(),
  express: new ExpressShipping(),
  overnight: new OvernightShipping(),
  international: new InternationalShipping(),
};

function getShippingCost(order: Order): number {
  const strategy = shippingStrategies[order.shippingMethod];
  return strategy?.calculateCost(order.weight) ?? 0;
}
