  constructor(private bank: { account: string; routing: string }) {}

  async process(amount: number): Promise<PaymentResult> {
    // Bank transfer specific logic
  }
}

class PaymentProcessor {
  async processPayment(amount: number, method: PaymentMethod): Promise<PaymentResult> {
    const strategy = this.createStrategy(method);
    return strategy.process(amount);
  }

  private createStrategy(method: PaymentMethod): PaymentStrategy {
    switch (method.type) {
      case 'credit_card':
        return new CreditCardPayment({ number: method.cardNumber, expiry: method.expiry, cvv: method.cvv });
      case 'bank_transfer':
