**Strategy Pattern** - Extract each formatter

```typescript
interface ReportFormatter {
  format(data: ReportData): string;
}

class HtmlFormatter implements ReportFormatter {
  format(data: ReportData): string {
    const rows = data.rows.map(row =>
      `<tr>${row.map(cell => `<td>${cell}</td>`).join('')}</tr>`
    ).join('');
    return `<html><body><h1>${data.title}</h1><table>${rows}</table></body></html>`;
  }
}

class CsvFormatter implements ReportFormatter {
  format(data: ReportData): string {
    return data.rows.map(row => row.join(',')).join('\n');
  }
}

class JsonFormatter implements ReportFormatter {
  format(data: ReportData): string {
    return JSON.stringify({ title: data.title, rows: data.rows });
  }
}

class MarkdownFormatter implements ReportFormatter {
  format(data: ReportData): string {
    const header = `| ${data.headers.join(' | ')} |`;
    const separator = `| ${data.headers.map(() => '---').join(' | ')} |`;
    const rows = data.rows.map(row => `| ${row.join(' | ')} |`).join('\n');
    return `# ${data.title}\n\n${header}\n${separator}\n${rows}`;
  }
}

const formatters: Record<string, ReportFormatter> = {
  html: new HtmlFormatter(),
  csv: new CsvFormatter(),
  json: new JsonFormatter(),
  markdown: new MarkdownFormatter(),
};

class ReportGenerator {
  generateReport(data: ReportData, format: string): string {
    const formatter = formatters[format];
    if (!formatter) throw new Error(`Unknown format: ${format}`);
    return formatter.format(data);
  }
}
```

