  parse(content: string): any {
    return yaml.parse(content);
  }
  serialize(data: any): string {
    return yaml.stringify(data);
  }
}

const handlers: Record<string, FormatHandler> = {
  json: new JsonHandler(),
  xml: new XmlHandler(),
  yaml: new YamlHandler(),
  csv: new CsvHandler(),
};

class DocumentConverter {
  convert(doc: Document, fromFormat: string, toFormat: string): string {
    const parser = handlers[fromFormat];
    const serializer = handlers[toFormat];

    if (!parser || !serializer) {
      throw new Error(`Unsupported format`);
    }

    const parsed = parser.parse(doc.content);
    return serializer.serialize(parsed);
  }
}
