```typescript
interface ValidationRule<T> {
  validate(value: T): string | null;
}

const required = (fieldName: string): ValidationRule<any> => ({
  validate: (value) => !value ? `${fieldName} is required` : null
});

const minLength = (min: number, fieldName: string): ValidationRule<string> => ({
  validate: (value) => value?.length < min ? `${fieldName} must be at least ${min} characters` : null
});

const pattern = (regex: RegExp, message: string): ValidationRule<string> => ({
  validate: (value) => !regex.test(value || '') ? message : null
});

const maxLength = (max: number, fieldName: string): ValidationRule<string> => ({
  validate: (value) => value?.length > max ? `${fieldName} must be less than ${max} characters` : null
});

interface FieldValidator<T> {
  field: keyof T;
  rules: ValidationRule<any>[];
}

const userValidators: FieldValidator<User>[] = [
  {
    field: 'email',
    rules: [
      required('Email'),
      pattern(/@/, 'Email must be valid'),
      maxLength(255, 'Email'),
    ],
  },
  {
    field: 'password',
    rules: [
      required('Password'),
      minLength(8, 'Password'),
      pattern(/[A-Z]/, 'Password must contain uppercase'),
      pattern(/[0-9]/, 'Password must contain number'),
    ],
  },
  {
    field: 'username',
    rules: [
      required('Username'),
      minLength(3, 'Username'),
      pattern(/^[a-zA-Z0-9_]+$/, 'Username can only contain letters, numbers, underscores'),
    ],
  },
];

function validate<T>(data: T, validators: FieldValidator<T>[]): string[] {
  return validators.flatMap(({ field, rules }) =>
    rules.map(rule => rule.validate(data[field])).filter(Boolean) as string[]
  );
}
```

