  taxRate: number;
  shippingRules: { minSubtotal: number; cost: number }[];
  discountRules: { condition: (cart: ShoppingCart) => boolean; rate: number }[];
}

const defaultPricing: PricingConfig = {
  taxRate: 0.08,
  shippingRules: [
    { minSubtotal: 100, cost: 0 },
    { minSubtotal: 50, cost: 5.99 },
    { minSubtotal: 0, cost: 9.99 },
  ],
  discountRules: [
    { condition: cart => cart.items.length > 10, rate: 0.1 },
    { condition: cart => cart.subtotal > 200, rate: 0.05 },
  ],
};

class CartItem {
  constructor(
    public readonly product: Product,
    public quantity: number
  ) {}

  get lineTotal(): number {
    return this.product.price * this.quantity;
  }
}

class ShoppingCart {
  items: CartItem[] = [];
  private pricing: PricingConfig;

  constructor(pricing: PricingConfig = defaultPricing) {
    this.pricing = pricing;
  }

  addItem(product: Product, quantity: number): void {
    const existing = this.items.find(i => i.product.id === product.id);
    if (existing) {
      existing.quantity += quantity;
    } else {
      this.items.push(new CartItem(product, quantity));
    }
  }

  get subtotal(): number {
    return this.items.reduce((sum, item) => sum + item.lineTotal, 0);
  }

  get tax(): number {
    return this.subtotal * this.pricing.taxRate;
  }

  get shipping(): number {
    const rule = this.pricing.shippingRules.find(r => this.subtotal >= r.minSubtotal);
    return rule?.cost ?? 0;
  }

  get discount(): number {
    const rule = this.pricing.discountRules.find(r => r.condition(this));
    return rule ? this.subtotal * rule.rate : 0;
  }

  get total(): number {
    return this.subtotal + this.tax + this.shipping - this.discount;
  }
}
