// Step functions
type PipelineStep<TIn, TOut> = (input: TIn) => TOut;

const readFile: PipelineStep<File, string> = (file) => 
  fs.readFileSync(file.path, 'utf-8');

const createParser = (type: string): PipelineStep<string, ParsedData> => {
  const parsers: Record<string, (content: string) => any> = {
    json: (content) => JSON.parse(content),
    csv: (content) => parseCsv(content),
    xml: (content) => parseXml(content),
  };
  return (content) => parsers[type]?.(content) ?? null;
};

const validate: PipelineStep<ParsedData, ValidatedData> = (data) => {
  if (!data?.records) throw new Error('Invalid data structure');
  return data as ValidatedData;
};

const transform: PipelineStep<ValidatedData, TransformedRecord[]> = (data) =>
  data.records.map((r) => ({
    id: r.id,
    name: r.name.trim().toLowerCase(),
    value: parseFloat(r.value),
  }));

const aggregate: PipelineStep<TransformedRecord[], Summary> = (records) => {
  const total = records.reduce((sum, r) => sum + r.value, 0);
  return { total, average: total / records.length, count: records.length };
};

const formatOutput = (records: TransformedRecord[], summary: Summary): ProcessedFile => ({
  records,
  summary,
  processedAt: new Date(),
});

// Composable pipeline
class FileProcessor {
  process(file: File): ProcessedFile {
    const content = readFile(file);
    const parsed = createParser(file.type)(content);
    const validated = validate(parsed);
    const transformed = transform(validated);
    const summary = aggregate(transformed);
    return formatOutput(transformed, summary);
  }
}
