const delimiters: Record<string, string> = {
  csv: ',',
  tsv: '\t',
  pipe: '|',
};

interface ExportOptions {
  format: 'csv' | 'tsv' | 'pipe';
  includeHeader?: boolean;
  includeFooter?: boolean;
}

class DataExporter {
  export(data: any[], options: ExportOptions): string {
    if (!data.length) return '';

    const delimiter = delimiters[options.format];
    if (!delimiter) throw new Error(`Unknown format: ${options.format}`);

    const parts: string[] = [];

    if (options.includeHeader) {
      parts.push(this.formatRow(Object.keys(data[0]), delimiter));
    }

    for (const row of data) {
      parts.push(this.formatRow(Object.values(row), delimiter));
    }

    if (options.includeFooter) {
      parts.push(`Total rows: ${data.length}`);
    }

    return parts.join('\n');
  }

  private formatRow(values: any[], delimiter: string): string {
    return values.join(delimiter);
  }
}

// Even simpler - add new formats by just adding to delimiters
delimiters['semicolon'] = ';';
delimiters['custom'] = ':::';
```

