```typescript
type PermissionRule = (user: User, document: Document) => boolean;

// Individual permission rules - composable and testable
const isAdmin: PermissionRule = (user) => user.role === 'admin';
const isOwner: PermissionRule = (user, doc) => user.id === doc.ownerId;
const isCollaborator: PermissionRule = (user, doc) => doc.collaborators.includes(user.id);
const isEditor: PermissionRule = (user) => user.role === 'editor';
const isNotLocked: PermissionRule = (_, doc) => doc.status !== 'locked';
const isNotArchived: PermissionRule = (_, doc) => doc.status !== 'archived';
const allowsEdit: PermissionRule = (_, doc) => doc.permissions.allowEdit;
const allowsShare: PermissionRule = (_, doc) => doc.permissions.allowShare;
const isPublic: PermissionRule = (_, doc) => doc.visibility === 'public';
const isSameOrg: PermissionRule = (user, doc) => 
  doc.visibility === 'organization' && user.organizationId === doc.organizationId;

// Combinators
const any = (...rules: PermissionRule[]): PermissionRule => 
  (user, doc) => rules.some(rule => rule(user, doc));

const all = (...rules: PermissionRule[]): PermissionRule => 
  (user, doc) => rules.every(rule => rule(user, doc));

// Permission definitions - clear and declarative
const permissions = {
  edit: any(
    isAdmin,
    all(isEditor, isNotLocked),
    isOwner,
    all(isCollaborator, allowsEdit)
  ),
  delete: any(
    isAdmin,
    all(isOwner, isNotArchived)
  ),
  share: any(
    isAdmin,
    isOwner,
    all(isCollaborator, allowsShare)
  ),
  view: any(
    isAdmin,
    isOwner,
    isCollaborator,
    isPublic,
    isSameOrg
  ),
};

class PermissionChecker {
  check(action: keyof typeof permissions, user: User, document: Document): boolean {
    return permissions[action](user, document);
  }

  canEdit = (user: User, doc: Document) => this.check('edit', user, doc);
  canDelete = (user: User, doc: Document) => this.check('delete', user, doc);
  canShare = (user: User, doc: Document) => this.check('share', user, doc);
  canView = (user: User, doc: Document) => this.check('view', user, doc);
}
```

## Risk Assessment
- Test coverage: Test individual rules, then compositions
- Migration: Add rule functions alongside existing code, then switch
- Risk level: Medium - authorization is critical, extensive testing required

