type FilterPredicate<T> = (item: T) => boolean;

interface FilterSpec<T, TFilters> {
  applies: (filters: TFilters) => boolean;
  predicate: (item: T, filters: TFilters) => boolean;
}

const productFilters: FilterSpec<Product, SearchFilters>[] = [
  {
    applies: (f) => !!f.category,
    predicate: (item, f) => item.category === f.category,
  },
  {
    applies: (f) => f.minPrice !== undefined,
    predicate: (item, f) => item.price >= f.minPrice!,
  },
  {
    applies: (f) => f.maxPrice !== undefined,
    predicate: (item, f) => item.price <= f.maxPrice!,
  },
  {
    applies: (f) => f.inStock !== undefined,
    predicate: (item, f) => item.inStock === f.inStock,
  },
  {
    applies: (f) => !!f.brand,
    predicate: (item, f) => item.brand === f.brand,
  },
  {
    applies: (f) => f.rating !== undefined,
    predicate: (item, f) => item.rating >= f.rating!,
  },
  {
    applies: (f) => f.tags?.length > 0,
    predicate: (item, f) => f.tags!.some(t => item.tags.includes(t)),
  },
];

function applyFilters<T, TFilters>(
  items: T[],
  filters: TFilters,
  specs: FilterSpec<T, TFilters>[]
): T[] {
  const activePredicates = specs
    .filter(spec => spec.applies(filters))
    .map(spec => (item: T) => spec.predicate(item, filters));

  return items.filter(item => activePredicates.every(pred => pred(item)));
}

class SearchService {
  search(query: string, filters: SearchFilters): SearchResult[] {
    const results = this.db.search(query);
    return applyFilters(results, filters, productFilters);
  }
}
```

