type State = 'idle' | 'loading' | 'success' | 'error';
type Action = 'FETCH' | 'SUCCESS' | 'ERROR' | 'CANCEL' | 'RESET' | 'RETRY';

interface Transition {
  target: State;
  effect?: () => void;
}

type TransitionTable = {
  [S in State]?: {
    [A in Action]?: Transition;
  };
};

class StateMachine {
  private state: State = 'idle';

  private transitions: TransitionTable = {
    idle: {
      FETCH: { target: 'loading', effect: () => this.startLoading() },
    },
    loading: {
      SUCCESS: { target: 'success', effect: () => this.showSuccess() },
      ERROR: { target: 'error', effect: () => this.showError() },
      CANCEL: { target: 'idle', effect: () => this.cancelLoading() },
    },
    success: {
      RESET: { target: 'idle', effect: () => this.reset() },
      FETCH: { target: 'loading', effect: () => this.startLoading() },
    },
    error: {
      RETRY: { target: 'loading', effect: () => this.startLoading() },
      RESET: { target: 'idle', effect: () => this.reset() },
    },
  };

  transition(action: Action): void {
    const stateTransitions = this.transitions[this.state];
    const transition = stateTransitions?.[action];

    if (!transition) {
      console.warn(`Invalid transition: ${this.state} + ${action}`);
      return;
    }

    this.state = transition.target;
    transition.effect?.();
  }

  getState(): State {
    return this.state;
  }

  // Can easily visualize or validate transitions
  getValidActions(): Action[] {
    return Object.keys(this.transitions[this.state] ?? {}) as Action[];
  }
}
```

## Risk Assessment
- Test coverage: Test each transition individually
- Migration: Build table from existing logic, verify same behavior
- Risk level: Low - state logic extracted, easy to verify

