interface PricingRule {
  name: string;
  priority: number;
  applies: (context: PricingContext) => boolean;
  calculate: (context: PricingContext, currentPrice: number) => number;
}

interface PricingContext {
  product: Product;
  customer: Customer;
  quantity: number;
  currentDate: Date;
}

const volumeDiscountRule: PricingRule = {
  name: 'Volume Discount',
  priority: 1,
  applies: () => true,
  calculate: (ctx, price) => {
    const tiers = [
      { min: 100, multiplier: 0.85 },
      { min: 50, multiplier: 0.90 },
      { min: 20, multiplier: 0.95 },
    ];
    const tier = tiers.find(t => ctx.quantity >= t.min);
    return tier ? price * tier.multiplier : price;
  },
};

const customerTierRule: PricingRule = {
  name: 'Customer Tier',
  priority: 2,
  applies: () => true,
  calculate: (ctx, price) => {
    const discounts: Record<string, number> = {
      platinum: 0.88,
      gold: 0.92,
      silver: 0.96,
    };
    return price * (discounts[ctx.customer.tier] ?? 1);
  },
};

const seasonalRule: PricingRule = {
  name: 'Seasonal Adjustment',
  priority: 3,
  applies: () => true,
  calculate: (ctx, price) => {
    const month = ctx.currentDate.getMonth();
    if (month === 11 || month === 0) return price * 1.1;
    if (month >= 6 && month <= 8) return price * 0.95;
    return price;
  },
};

const electronicsRule: PricingRule = {
  name: 'Electronics Clearance',
  priority: 4,
  applies: (ctx) => ctx.product.category === 'electronics' && ctx.product.age > 180,
  calculate: (_, price) => price * 0.9,
};

class PricingEngine {
  private rules: PricingRule[] = [
    volumeDiscountRule,
    customerTierRule,
    seasonalRule,
    electronicsRule,
    fashionSeasonRule,
  ].sort((a, b) => a.priority - b.priority);

  calculatePrice(product: Product, customer: Customer, quantity: number): number {
    const context: PricingContext = {
      product, customer, quantity, currentDate: new Date(),
    };

    let price = product.basePrice * quantity;

    for (const rule of this.rules) {
      if (rule.applies(context)) {
        price = rule.calculate(context, price);
      }
    }

    return Math.round(price * 100) / 100;
  }
}
