// Individual step commands
interface RegistrationStep {
  execute(context: RegistrationContext): Promise<void>;
  rollback?(context: RegistrationContext): Promise<void>;
}

interface RegistrationContext {
  userData: UserRegistrationData;
  hashedPassword?: string;
  user?: User;
}

const validateStep: RegistrationStep = {
  async execute(ctx) {
    if (!ctx.userData.email.includes('@')) throw new Error('Invalid email');
    if (ctx.userData.password.length < 8) throw new Error('Password too short');
    const existing = await db.users.findByEmail(ctx.userData.email);
    if (existing) throw new Error('User already exists');
  },
};

const hashPasswordStep: RegistrationStep = {
  async execute(ctx) {
    ctx.hashedPassword = await bcrypt.hash(ctx.userData.password, 10);
  },
};

const createUserStep: RegistrationStep = {
  async execute(ctx) {
    ctx.user = await db.users.create({
      email: ctx.userData.email,
      password: ctx.hashedPassword!,
      name: ctx.userData.name,
    });
  },
  async rollback(ctx) {
    if (ctx.user) await db.users.delete(ctx.user.id);
  },
};

const createSettingsStep: RegistrationStep = {
  async execute(ctx) {
    await db.userSettings.create({
      userId: ctx.user!.id,
      theme: 'light',
      notifications: true,
    });
  },
};

// Saga orchestrator
async function executeRegistration(userData: UserRegistrationData): Promise<User> {
  const steps: RegistrationStep[] = [
    validateStep,
    hashPasswordStep,
    createUserStep,
    createSettingsStep,
  ];

  const postCommitSteps: RegistrationStep[] = [
    sendWelcomeEmailStep,
    trackAnalyticsStep,
    grantCreditsStep,
  ];

  const context: RegistrationContext = { userData };
  const completedSteps: RegistrationStep[] = [];

  try {
    // Critical steps with rollback
    for (const step of steps) {
      await step.execute(context);
      completedSteps.push(step);
    }

    // Fire-and-forget post-commit steps
    await Promise.allSettled(
      postCommitSteps.map(step => step.execute(context))
    );

    return context.user!;
  } catch (error) {
    // Rollback in reverse order
    for (const step of completedSteps.reverse()) {
      await step.rollback?.(context).catch(console.error);
    }
    throw error;
  }
}
```

