```typescript
enum LogLevel {
  DEBUG = 0,
  INFO = 1,
  WARN = 2,
  ERROR = 3,
}

interface LogLevelConfig {
  name: string;
  output: (msg: string) => void;
}

const levelConfigs: Record<LogLevel, LogLevelConfig> = {
  [LogLevel.DEBUG]: { name: 'DEBUG', output: console.log },
  [LogLevel.INFO]: { name: 'INFO', output: console.log },
  [LogLevel.WARN]: { name: 'WARN', output: console.warn },
  [LogLevel.ERROR]: { name: 'ERROR', output: console.error },
};

class Logger {
  private minLevel: LogLevel;

  constructor(minLevel?: LogLevel) {
    this.minLevel = minLevel ?? this.parseEnvLevel();
  }

  private parseEnvLevel(): LogLevel {
    const envLevel = process.env.LOG_LEVEL?.toUpperCase();
    const mapping: Record<string, LogLevel> = {
      DEBUG: LogLevel.DEBUG,
      INFO: LogLevel.INFO,
      WARN: LogLevel.WARN,
      ERROR: LogLevel.ERROR,
    };
    return mapping[envLevel ?? ''] ?? LogLevel.INFO;
  }

  private log(level: LogLevel, message: string, context?: object): void {
    if (level < this.minLevel) return;

    const config = levelConfigs[level];
    const timestamp = new Date().toISOString();
    const contextStr = context ? ` ${JSON.stringify(context)}` : '';
    config.output(`[${timestamp}] [${config.name}] ${message}${contextStr}`);
  }

  debug = (message: string, context?: object) => this.log(LogLevel.DEBUG, message, context);
  info = (message: string, context?: object) => this.log(LogLevel.INFO, message, context);
  warn = (message: string, context?: object) => this.log(LogLevel.WARN, message, context);
  error = (message: string, context?: object) => this.log(LogLevel.ERROR, message, context);
}
