```typescript
type Validator = (value: any, form: any) => string | null;

// Reusable validators
const required = (fieldName: string): Validator => 
  (value) => !value ? `${fieldName} is required` : null;

const minLength = (min: number, fieldName: string): Validator => 
  (value) => value?.length < min ? `${fieldName} must be at least ${min} characters` : null;

const pattern = (regex: RegExp, message: string): Validator => 
  (value) => value && !regex.test(value) ? message : null;

const matches = (otherField: string, message: string): Validator => 
  (value, form) => value !== form[otherField] ? message : null;

const isTrue = (message: string): Validator => 
  (value) => value !== true ? message : null;

// Composed field validators
const emailValidators = [
  required('Email'),
  pattern(/^[^@]+@[^@]+$/, 'Email is invalid'),
];

const passwordValidators = [
  required('Password'),
  minLength(8, 'Password'),
  pattern(/[A-Z]/, 'Password must contain uppercase'),
  pattern(/[0-9]/, 'Password must contain a number'),
];

const nameValidators = [
  required('Name'),
  minLength(2, 'Name'),
];

// Schema definitions
type ValidationSchema<T> = { [K in keyof T]?: Validator[] };

const registrationSchema: ValidationSchema<RegistrationForm> = {
  email: emailValidators,
  password: passwordValidators,
  confirmPassword: [required('Confirm password'), matches('password', 'Passwords must match')],
  name: nameValidators,
  acceptTerms: [isTrue('You must accept the terms')],
};

const loginSchema: ValidationSchema<LoginForm> = {
  email: emailValidators,
  password: [required('Password')],
};

const profileSchema: ValidationSchema<ProfileForm> = {
  name: nameValidators,
  phone: [pattern(/^\d{10,}$/, 'Phone number is invalid')],
};

// Generic validator
function validate<T>(form: T, schema: ValidationSchema<T>): ValidationResult {
  const errors: string[] = [];

  for (const [field, validators] of Object.entries(schema)) {
    for (const validator of validators ?? []) {
      const error = validator(form[field as keyof T], form);
      if (error) {
        errors.push(error);
        break; // Stop at first error for this field
      }
    }
  }

  return { isValid: errors.length === 0, errors };
}

// Usage
class FormValidator {
  validateRegistrationForm = (form: RegistrationForm) => validate(form, registrationSchema);
  validateLoginForm = (form: LoginForm) => validate(form, loginSchema);
  validateProfileForm = (form: ProfileForm) => validate(form, profileSchema);
}
```

